import { ConflictError, ValidationError } from "./errors";

export const TASK_STATUSES = ["todo", "in_progress", "done"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];

export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
}

export interface TaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status?: TaskStatus;
  assigneeId?: string;
  createdAt: Date;
}

export class Task {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate: Date | undefined;
  readonly createdAt: Date;
  private _status: TaskStatus;
  private _assigneeId: string | undefined;
  private _completedAt: Date | undefined;

  constructor(props: TaskProps) {
    const title = props.title.trim();
    if (title.length === 0) {
      throw new ValidationError("Task title must not be empty");
    }
    if (props.dueDate !== undefined && Number.isNaN(props.dueDate.getTime())) {
      throw new ValidationError("Task due date is invalid");
    }
    this.id = props.id;
    this.projectId = props.projectId;
    this.title = title;
    this.description = props.description;
    this.dueDate = props.dueDate;
    this.createdAt = props.createdAt;
    this._status = props.status ?? "todo";
    this._assigneeId = props.assigneeId;
    this._completedAt = this._status === "done" ? props.createdAt : undefined;
  }

  get status(): TaskStatus {
    return this._status;
  }

  get assigneeId(): string | undefined {
    return this._assigneeId;
  }

  get completedAt(): Date | undefined {
    return this._completedAt;
  }

  assignTo(userId: string): void {
    this._assigneeId = userId;
  }

  markDone(now: Date): void {
    if (this._status === "done") {
      throw new ConflictError(`Task '${this.id}' is already done`);
    }
    this._status = "done";
    this._completedAt = now;
  }
}

export interface TaskFilter {
  status?: TaskStatus;
  assigneeId?: string;
}

export interface TaskRepository {
  save(task: Task): void;
  findById(id: string): Task | undefined;
  findByProject(projectId: string, filter?: TaskFilter): Task[];
}

